<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import AppDialog from './AppDialog.vue';
type Change={aplicada:boolean;instrumento:string;citacao?:string};
type Revision={campo:string;aditivo:string;acao:string;justificativa:string};
type View={versao:string|null;desatualizado:boolean;vinculos:Array<{aditivo:string;justificativa:string}>;revisoes:Revision[];historico:Array<{versao:string;criado_em:string;ator_id:number}>;resultado:null|{padrao:{campos:Record<string,string>};pendencias:string[];historico:Record<string,Change[]>}};
const props=defineProps<{base:string;canEdit:boolean;clients:Array<{id:number;razao_social:string}>;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>}>();
const emit=defineEmits<{success:[message:string]}>();
const view=ref<View|null>(null),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),clientId=ref('');
const review=ref<{campo:string;change:Change;version:string}|null>(null),decision=ref('manter'),value=ref(''),reason=ref('');let generation=0,alive=true;
const label=(field:string)=>{const text=field.replace(/^s\d+_/,'').replaceAll('_',' ');return text.charAt(0).toUpperCase()+text.slice(1);};
const candidates=computed(()=>Object.entries(view.value?.resultado?.historico??{}).flatMap(([campo,items])=>items.filter(item=>!item.aplicada).map(change=>({campo,change}))));
const finalReady=computed(()=>!!view.value?.versao&&!view.value.desatualizado&&!!view.value.resultado&&!view.value.resultado.pendencias.length);
async function load(){const current=++generation;view.value=null;error.value='';review.value=null;if(!props.base)return;loading.value=true;try{const data=await props.request<View>('/api/contexto/interpretacoes?base='+encodeURIComponent(props.base));if(alive&&current===generation)view.value=data;}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
async function consolidate(){if(busy.value||!props.canEdit)return;const current=generation;busy.value=true;error.value='';try{const result=await props.request<View>('/api/contexto/interpretacoes/consolidar','POST',{base:props.base});if(!alive||current!==generation)return;view.value=result;emit('success','Consolidação atualizada.');}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{busy.value=false;}}
function openReview(campo:string,change:Change){if(!view.value?.versao||view.value.desatualizado||!props.canEdit)return;review.value={campo,change,version:view.value.versao};decision.value='manter';value.value='';reason.value='';formError.value='';}
async function saveReview(){if(busy.value||!review.value||!props.canEdit||view.value?.desatualizado)return;const current=generation,target=review.value;busy.value=true;formError.value='';try{await props.request('/api/contexto/revisoes','POST',{base:props.base,campo:target.campo,aditivo:target.change.instrumento,acao:decision.value,valor:decision.value==='manual'?value.value:'',justificativa:reason.value,versao:target.version});if(!alive||current!==generation)return;review.value=null;emit('success','Revisão registrada.');await load();}catch(cause){if(alive&&current===generation)formError.value=(cause as Error).message;}finally{busy.value=false;}}
async function report(format:'pdf'|'md'){if(!finalReady.value||!clientId.value||busy.value)return;const current=generation,base=props.base;busy.value=true;error.value='';try{const file=await props.download(`/api/contexto/relatorio?base=${encodeURIComponent(base)}&cliente=${encodeURIComponent(clientId.value)}&formato=${format}`);if(!alive||current!==generation)return;const url=URL.createObjectURL(file.blob),link=document.createElement('a');link.href=url;link.download=base.replace(/\W/g,'_')+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{busy.value=false;}}
watch(()=>props.base,()=>{clientId.value='';void load();},{immediate:true});onBeforeUnmount(()=>{alive=false;generation++;});
</script>
<template><section class="consolidation-panel"><header class="document-panel-heading"><div><h3>Consolidação e revisões</h3><p>Confira as alterações dos aditivos e registre decisões com base no original.</p></div><button v-if="base" class="secondary" type="button" :disabled="loading||busy" @click="load">Atualizar versão</button></header><p v-if="!base">Selecione uma CCT para consultar.</p><p v-if="loading" role="status">Carregando consolidação…</p><p v-if="error" role="alert">{{ error }}</p><template v-if="view"><div class="document-summary"><article><small>Versão consultada</small><strong class="version-label">{{ view.versao?.slice(0,12)||'Não gerada' }}</strong></article><article><small>Pendências</small><strong>{{ view.resultado?.pendencias.length??'—' }}</strong></article><article><small>Aditivos vinculados</small><strong>{{ view.vinculos.length }}</strong></article><article><small>Histórico</small><strong>{{ view.historico.length }}</strong></article></div><p v-if="view.desatualizado" class="consolidation-warning" role="status">A consolidação está desatualizada. Atualize antes de revisar ou exportar.</p><p v-else-if="view.resultado?.pendencias.length" class="consolidation-warning">Há pendências que impedem os relatórios finais e a publicação.</p><button v-if="canEdit" class="secondary" type="button" :disabled="busy||loading" @click="consolidate">{{ busy?'Processando…':'Consolidar neste escritório' }}</button><p v-for="link in view.vinculos" :key="link.aditivo">Aditivo {{ link.aditivo }} · {{ link.justificativa }}</p>
<template v-if="view.resultado"><details class="consolidated-fields"><summary>Regras consolidadas · {{ Object.keys(view.resultado.padrao.campos).length }} campos</summary><div class="document-info-grid"><article v-for="(text,field) in view.resultado.padrao.campos" :key="field"><small>{{ label(String(field)) }}</small><p>{{ text }}</p></article></div></details><h4>Alterações para conferência</h4><p v-if="!candidates.length">Nenhuma alteração aguardando conferência.</p><article v-for="(item,index) in candidates" :key="item.campo+item.change.instrumento+index" class="document-related"><strong>{{ label(item.campo) }}</strong><p>Aditivo {{ item.change.instrumento }}</p><blockquote>{{ item.change.citacao||'Citação não disponível.' }}</blockquote><p v-if="view.revisoes.find(revision=>revision.campo===item.campo&&revision.aditivo===item.change.instrumento)">Decisão: {{ view.revisoes.find(revision=>revision.campo===item.campo&&revision.aditivo===item.change.instrumento)?.acao }} · {{ view.revisoes.find(revision=>revision.campo===item.campo&&revision.aditivo===item.change.instrumento)?.justificativa }}</p><button v-if="canEdit&&!view.desatualizado&&view.versao" class="secondary" type="button" :disabled="busy" @click="openReview(item.campo,item.change)">Revisar {{ label(item.campo) }}</button></article>
<section v-if="finalReady" class="report-actions"><h4>Relatório final</h4><label>Cliente do relatório<select v-model="clientId"><option value="">Selecione uma empresa</option><option v-for="client in clients" :key="client.id" :value="String(client.id)">{{ client.razao_social }}</option></select></label><div><button class="secondary" type="button" :disabled="!clientId||busy" @click="report('pdf')">Baixar relatório PDF</button><button class="secondary" type="button" :disabled="!clientId||busy" @click="report('md')">Baixar relatório MD</button></div></section></template>
<details><summary>Histórico de versões</summary><ul><li v-for="item in view.historico" :key="item.versao">{{ new Date(item.criado_em).toLocaleString('pt-BR') }} · Versão {{ item.versao.slice(0,16) }} · Usuário {{ item.ator_id }}</li></ul></details></template></section>
<AppDialog v-if="review" :title="'Revisar '+label(review.campo)" :busy="busy" @close="review=null"><h3>Regra atual</h3><p>{{ view?.resultado?.padrao.campos[review.campo]||'Não informada' }}</p><h3>Alteração proposta</h3><p>Aditivo {{ review.change.instrumento }}</p><blockquote>{{ review.change.citacao||'Citação não disponível.' }}</blockquote><form class="vue-form" @submit.prevent="saveReview"><label>Decisão<select v-model="decision"><option value="manter">Manter regra anterior</option><option value="aplicar_aditivo">Usar trecho literal do aditivo</option><option value="manual">Informar regra revisada</option></select></label><label v-if="decision==='manual'">Texto da regra revisada<textarea v-model="value" required maxlength="3000"></textarea></label><label>Justificativa da revisão<textarea v-model="reason" required minlength="8" maxlength="2500"></textarea></label><p v-if="formError" role="alert">{{ formError }}</p><footer><button class="secondary" type="button" :disabled="busy" @click="review=null">Cancelar</button><button class="secondary" type="submit" :disabled="busy">Registrar revisão</button></footer></form></AppDialog></template>
